-- -----------------------------------
-- Table structure for `site_circle`
-- -----------------------------------

DROP TABLE IF EXISTS `site_circle`;
CREATE TABLE `site_circle` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ATMID` varchar(128) CHARACTER SET utf8mb4 DEFAULT NULL,
  `site_type` varchar(120) CHARACTER SET utf8mb4 DEFAULT NULL,
  `Bank` varchar(128) CHARACTER SET utf8mb4 DEFAULT NULL,
  `Zonal` varchar(25) CHARACTER SET utf8mb4 DEFAULT NULL,
  `Circle` text CHARACTER SET utf8mb4,
  `sn` int(3) NOT NULL DEFAULT '0',
  `unique_id` varchar(50) CHARACTER SET utf8mb4 NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=4139 DEFAULT CHARSET=latin1;

